    public int countDistinctIslands(int[][] grid) {

        if ( grid == null || grid.length == 0 ) return 0;

        int n = grid.length;
        int m = grid[0].length;

        int direction [][] = new int[][]{{0, 1}, {1, 0}, {0 , -1}, {-1, 0}};
        boolean [][] visited = new boolean[grid.length][grid[0].length];
        Set<String> shapes = new HashSet<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if ( grid[i][j] == 1 && !visited[i][j] ) {
                    // bfs or dfs call to explore the island and mark it visited
                    // add the shape of the island to a set to count distinct shapes
                    bfs(grid, visited, i, j, direction, shapes);
                }
            }
        }

        shapes.forEach(i-> System.out.println(i));

        return shapes.size();
    }

    public void bfs(int [][] grid, boolean [][] visited, int startI, int startJ, int direction[][], Set<String> shapes) {
        
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{startI, startJ});
        visited[startI][startJ] = true;
        
        List<String> island = new ArrayList<>();
        
        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            int i = cell[0];
            int j = cell[1];
            
            // Store relative coordinates from starting point
            island.add((i - startI) + "," + (j - startJ));
            
            for (int k = 0; k < 4; k++) {
                int newX = i + direction[k][0];
                int newY = j + direction[k][1];
                
                if (isValid(grid, visited, newX, newY)) {
                    visited[newX][newY] = true;
                    queue.offer(new int[]{newX, newY});
                }
            }
        }

        // Sort to get a canonical form (same shape always produces same string)
        Collections.sort(island);
        shapes.add(String.join("|", island));
    }

    boolean isValid(int [][] grid, boolean [][] visited, int i, int j) {
        return i >= 0 && i < grid.length && j >= 0 && j < grid[0].length && grid[i][j] == 1 && !visited[i][j];
    }

    public char[][] fill(char[][] mat) {

        if ( mat == null || mat.length == 0 ) return null;

        int n = mat.length;
        int m = mat[0].length;

        boolean [][] visited = new boolean[n][m];
        int direction [][] = new int[][]{{0, 1}, {1, 0}, {0 , -1}, {-1, 0}};

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                
                // first row or last row 
                if ( i == 0 || i == n - 1 || j == 0 || j == m - 1 ) {
                    
                    if ( mat[i][j] == 'O' && !visited[i][j] ) {
                        // bfs call to explore all O connected to boundary and mark them visited
                        bfsChar(mat, visited, i, j, direction);
                    }

                }

            }
        }

        // loop for internal cells and fill O with X if not visited
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if ( mat[i][j] == 'O' && !visited[i][j] ) {
                    mat[i][j] = 'X';
                }
            }
        }

        return mat;
    }

    void bfsChar(char [][] mat, boolean [][] visited, int startI, int startJ, int direction[][]) {
        
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{startI, startJ});
        visited[startI][startJ] = true;
        
        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            int i = cell[0];
            int j = cell[1];
            
            for (int k = 0; k < 4; k++) {
                int newX = i + direction[k][0];
                int newY = j + direction[k][1];
                
                if (isValidChar(mat, visited, newX, newY)) {
                    visited[newX][newY] = true;
                    queue.offer(new int[]{newX, newY});
                }
            }
        }
    }

    boolean isValidChar(char [][] mat, boolean [][] visited, int i, int j) {
        return i >= 0 && i < mat.length && j >= 0 && j < mat[0].length && mat[i][j] == 'O' && !visited[i][j];
    }


    public char[][] fill2(char[][] mat) {
        
        if ( mat == null || mat.length == 0 ) return null;

        int n = mat.length;
        int m = mat[0].length;

        boolean [][] visited = new boolean[n][m];
        int direction [][] = new int[][]{{0, 1}, {1, 0}, {0 , -1}, {-1, 0}};

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                
                // first row or last row 
                if ( i == 0 || i == n - 1 || j == 0 || j == m - 1 ) { // correct ?
                    
                    if ( mat[i][j] == 'O' && !visited[i][j] ) {
                        // dfs call to explore all O connected to boundary and mark them visited
                        dfs(mat, visited, i, j, direction);
                    }

                }

            }
        }

        // loop for internal cells and fill O with X if not visited
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if ( mat[i][j] == 'O' && !visited[i][j] ) {
                    mat[i][j] = 'X';
                }
            }
        }

        return mat;
    }

    void dfs(char [][] mat, boolean [][] visited, int i, int j, int direction[][]) {

        visited[i][j] = true;

        for (int k = 0; k < 4; k++) {
            int newX = i + direction[k][0];
            int newY = j + direction[k][1];

            if (isValidChar(mat, visited, newX, newY) ) {
                dfs(mat, visited, newX, newY, direction);
            }
        }

    }

